import java.util.*;

class Solution {
    public int rob(TreeNode root) {
        return rob(root, new HashMap<>());
    }

    private int rob(TreeNode node, Map<TreeNode, Integer> memo) {
        if (node == null) return 0;
        if (memo.containsKey(node)) return memo.get(node);

        int take = node.val;
        if (node.left != null) take += rob(node.left.left, memo) + rob(node.left.right, memo);
        if (node.right != null) take += rob(node.right.left, memo) + rob(node.right.right, memo);

        int skip = rob(node.left, memo) + rob(node.right, memo);
        int best = Math.max(take, skip);
        memo.put(node, best);
        return best;
    }
}

class Solution {
    public int rob(TreeNode root) {
        int[] res = dfs(root);
        return Math.max(res[0], res[1]);
    }

    private int[] dfs(TreeNode node) {
        if (node == null) return new int[]{0, 0};

        int[] left = dfs(node.left);
        int[] right = dfs(node.right);

        int noTake = Math.max(left[0], left[1]) + Math.max(right[0], right[1]);
        int take = node.val + left[0] + right[0];
        return new int[]{noTake, take};
    }
}
